  "vps_vs_dedicated": [
    {
      "topic": "Network",
      "vps": "keep the provider's config (netplan / cloud-init): `server-preconfig.sh` doesn't touch it, Enter = `keep`",
      "dedicated": "save it so it survives reboots: `server-preconfig.sh --static-ip current`, or a DHCP reservation on the router"
    },
    {
      "topic": "Console if SSH breaks",
      "vps": "the provider's web console",
      "dedicated": "IPMI / iDRAC / iLO / KVM, the host's rescue mode, or a screen and keyboard"
    },
    {
      "topic": "Power",
      "vps": "handled by the provider",
      "dedicated": "BIOS *Restore on AC Power Loss* = **Power On**"
    },
    {
      "topic": "Reaching it",
      "vps": "public IP: open 80/443 (`EXPOSE_WEB=yes`) or use a tunnel",
      "dedicated": "often behind NAT: Tailscale for SSH and the panel, a Cloudflare Tunnel for the apps"
    }
  ],
